+
+export const useHealthCheck = (options?: UseQueryOptions<HealthCheckResponse>) => {
+  return useQuery({
+    queryKey: queryKeys.health,
+    queryFn: api.checkHealth,
+    refetchInterval: 30000, // Refetch every 30 seconds
+    ...options,
+  });
